<?php
session_start(); if(($_SESSION["role"]??"")!=="admin"||empty($_SESSION["user_id"])){header("Location: login.php");exit;} require "connection.php"; mysqli_report(MYSQLI_REPORT_OFF);
mysqli_query($conn, "CREATE TABLE IF NOT EXISTS contributions (id INT AUTO_INCREMENT PRIMARY KEY, contributor VARCHAR(25) NOT NULL, plantname VARCHAR(25) NOT NULL, photos TEXT NULL, comments TEXT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, committed_at DATETIME NULL)");
function plantEscape($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,"UTF-8");}
if(empty($_SESSION["admin_csrf"]))$_SESSION["admin_csrf"]=bin2hex(random_bytes(32));$csrf=$_SESSION["admin_csrf"];$message="";
$hasCommitted=mysqli_query($conn,"SHOW COLUMNS FROM contributions LIKE 'committed_at'");if($hasCommitted&&mysqli_num_rows($hasCommitted)===0)mysqli_query($conn,"ALTER TABLE contributions ADD COLUMN committed_at DATETIME NULL");
if($_SERVER["REQUEST_METHOD"]==="POST"){if(!isset($_POST["csrf_token"])||!hash_equals($csrf,(string)$_POST["csrf_token"])){http_response_code(400);exit("Invalid form token.");}$id=(int)($_POST["id"]??0);$action=(string)($_POST["action"]??"");
 if($action==="review"){$status=(string)($_POST["status"]??"pending");if(!in_array($status,["pending","approved","rejected"],true))$message="Invalid review status.";else{$s=mysqli_prepare($conn,"UPDATE contributions SET status=? WHERE id=?");mysqli_stmt_bind_param($s,"si",$status,$id);$message=mysqli_stmt_execute($s)?"Review status updated.":"Could not update the status.";}}
 elseif($action==="commit"){$s=mysqli_prepare($conn,"UPDATE contributions SET status='approved', committed_at=NOW() WHERE id=?");mysqli_stmt_bind_param($s,"i",$id);$message=mysqli_stmt_execute($s)?"Plant committed to the public Contribution page.":"Could not publish this submission.";}
 elseif($action==="delete"){$f=mysqli_prepare($conn,"SELECT photos FROM contributions WHERE id=?");mysqli_stmt_bind_param($f,"i",$id);mysqli_stmt_execute($f);$r=mysqli_fetch_assoc(mysqli_stmt_get_result($f));$d=mysqli_prepare($conn,"DELETE FROM contributions WHERE id=?");mysqli_stmt_bind_param($d,"i",$id);$message=mysqli_stmt_execute($d)?"Submission deleted.":"Could not delete submission.";if($r){$pics=json_decode((string)$r["photos"],true)?:[];foreach($pics as $pic){$file=__DIR__."/".ltrim((string)$pic,"/");$base=realpath(__DIR__."/uploads/contributions");$real=realpath($file);if($real&&$base&&strpos($real,$base.DIRECTORY_SEPARATOR)===0&&is_file($real))@unlink($real);}}}
 elseif($action==="edit"){$name=trim((string)($_POST["plantname"]??""));$person=trim((string)($_POST["contributor"]??""));$comments=trim((string)($_POST["comments"]??""));if($name===""||$person===""||strlen($name)>25||strlen($person)>25||strlen($comments)>5000)$message="Check the plant name, contributor and comments.";else{$s=mysqli_prepare($conn,"UPDATE contributions SET plantname=?, contributor=?, comments=? WHERE id=?");mysqli_stmt_bind_param($s,"sssi",$name,$person,$comments,$id);$message=mysqli_stmt_execute($s)?"Submission details updated.":"Could not update submission.";}}
}
$edit=null;if(isset($_GET["edit"])){$id=(int)$_GET["edit"];$s=mysqli_prepare($conn,"SELECT * FROM contributions WHERE id=?");mysqli_stmt_bind_param($s,"i",$id);mysqli_stmt_execute($s);$edit=mysqli_fetch_assoc(mysqli_stmt_get_result($s))?:null;}$rows=mysqli_query($conn,"SELECT id,contributor,plantname,photos,comments,status,created_at,committed_at FROM contributions ORDER BY created_at DESC,id DESC");
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Plant Contributions | Plantify Admin</title><link rel="stylesheet" href="styles/style.css?v=admin-style-2"></head><body class="admin-page"><?php include "admin_header.php"; ?><main class="admin-shell"><h1>Plant submissions</h1><p>Check the submitted plant details and photos before publishing them on the public Contribution page.</p><?php if($message!==''): ?><p class="admin-message" role="status"><?=plantEscape($message)?></p><?php endif; ?><?php if($edit): ?><section class="admin-card"><h2>Edit submission</h2><form class="admin-form" method="post"><input type="hidden" name="csrf_token" value="<?=plantEscape($csrf)?>"><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=(int)$edit["id"]?>"><label>Plant name<input name="plantname" maxlength="25" required value="<?=plantEscape($edit["plantname"])?>"></label><label>Contributor<input name="contributor" maxlength="25" required value="<?=plantEscape($edit["contributor"])?>"></label><label class="admin-wide">Comments<textarea name="comments" rows="4"><?=plantEscape($edit["comments"]??"")?></textarea></label><div class="admin-actions"><button type="submit">Save changes</button><a href="view_contribution_form.php">Cancel</a></div></form></section><?php endif; ?>
<section class="admin-card"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Plant / contributor</th><th>Submitted photos</th><th>Comments</th><th>Submitted</th><th>Review</th><th>Actions</th></tr></thead><tbody><?php if($rows&&mysqli_num_rows($rows)):while($r=mysqli_fetch_assoc($rows)):$photos=json_decode((string)($r["photos"]??""),true);$photos=is_array($photos)?$photos:[]; ?><tr><td><strong><?=plantEscape($r["plantname"])?></strong><br><?=plantEscape($r["contributor"])?></td><td><?php foreach($photos as $photo): ?><a href="<?=plantEscape($photo)?>" target="_blank" rel="noopener"><img class="admin-submission-photo" src="<?=plantEscape($photo)?>" alt="Submitted plant photo"></a><?php endforeach; ?><?php if(!$photos): ?>No photos<?php endif; ?></td><td><?=nl2br(plantEscape($r["comments"]??""))?></td><td><?=plantEscape($r["created_at"]??"")?></td><td><?=plantEscape(ucfirst($r["status"]??"pending"))?><?php if(!empty($r["committed_at"])): ?><br><small>Published</small><?php endif; ?></td><td class="admin-row-actions"><a href="view_contribution_form.php?edit=<?=(int)$r["id"]?>">Edit</a><form method="post"><input type="hidden" name="csrf_token" value="<?=plantEscape($csrf)?>"><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?=(int)$r["id"]?>"><select name="status"><option value="pending" <?=($r["status"]??"")==="pending"?"selected":""?>>Pending</option><option value="approved" <?=($r["status"]??"")==="approved"?"selected":""?>>Approved</option><option value="rejected" <?=($r["status"]??"")==="rejected"?"selected":""?>>Rejected</option></select><button type="submit">Save status</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=plantEscape($csrf)?>"><input type="hidden" name="action" value="commit"><input type="hidden" name="id" value="<?=(int)$r["id"]?>"><button type="submit">Commit</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=plantEscape($csrf)?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r["id"]?>"><button type="submit" class="admin-danger">Delete</button></form></td></tr><?php endwhile; else: ?><tr><td colspan="6">No contribution submissions yet.</td></tr><?php endif; ?></tbody></table></div></section></main></body></html>
